import java.util.Scanner;

public class Main {
    static final int N = 505;
    static int n, m, mod;
    static int[][] C = new int[N][N];
    static long[] f = new long[N], g = new long[N];
    static long[][] ff = new long[N][N], gg = new long[N][N];

    static void add(long[] x, int y) {
        x[0] += y;
        if (x[0] >= mod) x[0] -= mod;
    }

    static void add(long[] x, long y) {
        x[0] += y;
        if (x[0] >= mod) x[0] -= mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        mod = sc.nextInt();

        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % mod;
            }
        }

        f[0] = 1;
        g[0] = 0;
        for (int i = 1; i <= n; i++) {
            f[i] = 0;
            g[i] = 0;
            for (int j = 1; j <= i; j++) {
                long temp1 = (f[j - 1] * f[i - j]) % mod;
                long temp2 = (long) C[i - 1][j - 1] * (i + 1) % mod;
                add(new long[]{f[i]}, (int) (temp1 * temp2 % mod));

                long temp3 = (g[j - 1] * f[i - j]) % mod;
                add(new long[]{g[i]}, (int) (temp3 * temp2 % mod));

                long temp4 = (g[i - j] * f[j - 1]) % mod;
                add(new long[]{g[i]}, (int) (temp4 * temp2 % mod));

                int s = 0;
                for (int k = 1; k <= i; k++) {
                    s += Math.abs(k - j);
                }
                add(new long[]{g[i]}, (int) (f[j - 1] * f[i - j] % mod * s % mod * C[i - 1][j - 1] % mod));
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                ff[i][j] = 0;
                gg[i][j] = 0;
            }
        }

        ff[0][0] = 1;
        gg[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                if (j == i) {
                    ff[i][j] = f[i];
                    gg[i][j] = g[i];
                    continue;
                }
                ff[i][j] = ff[i - 1][j];
                gg[i][j] = gg[i - 1][j];
                for (int k = 1; k <= j; k++) {
                    long temp1 = (ff[i - k - 1][j - k] * f[k]) % mod;
                    long temp2 = C[j][k];
                    add(new long[]{ff[i][j]}, (int) (temp1 * temp2 % mod));

                    long temp3 = (ff[i - k - 1][j - k] * g[k]) % mod;
                    add(new long[]{gg[i][j]}, (int) (temp3 * temp2 % mod));

                    long temp4 = (gg[i - k - 1][j - k] * f[k]) % mod;
                    add(new long[]{gg[i][j]}, (int) (temp4 * temp2 % mod));
                }
            }
        }

        System.out.println(gg[n][m]);
        sc.close();
    }
}
